func subcommandRegisterFuncs() []func(*Options) (*cobra.Command, error) {
	return []func(*Options) (*cobra.Command, error){
		versionCmd,
		completionCmd,
		deployCmd,
		destroyCmd,
		startCmd,
		stopCmd,
		restartCmd,
		execCmd,
		generateCmd,
		graphCmd,
		eventsCmd,
		inspectCmd,
		logsCmd,
		redeployCmd,
		saveCmd,
		toolsCmd,
		validateCmd,
	}
}

// Entrypoint returns the root cobra command to be executed or errors if it cannot do so.
func Entrypoint() (*cobra.Command, error) {
	o := GetOptions()

	c := &cobra.Command{
		Use:   "containerlab",
		Short: "deploy container based lab environments with a user-defined interconnections",
		PersistentPreRunE: func(cobraCmd *cobra.Command, _ []string) error {
			return preRunFn(cobraCmd, o)
		},
		Aliases:      []string{"clab"},
		SilenceUsage: true,
	}

	c.PersistentFlags().CountVarP(
		&o.Global.DebugCount,
		"debug",
		"d",
		"enable debug mode",
	)
	c.PersistentFlags().StringVarP(
		&o.Global.TopologyFile,
		"topo",
		"t",
		o.Global.TopologyFile,
		"path to the topology definition file, a directory containing one, 'stdin', or a URL",
	)
	c.PersistentFlags().StringArrayVarP(
		&o.Global.VarsFiles,
		"vars",
		"",
		o.Global.VarsFiles,
		"path to a topology template variables file (can be specified multiple times)",
	)
	c.PersistentFlags().StringVarP(
		&o.Global.TopologyName,
		"name",
		"",
		o.Global.TopologyName,
		"lab/topology name")
	c.PersistentFlags().StringVar(
		&o.Global.Namespace,
		"namespace",
		o.Global.Namespace,
		"Kubernetes namespace override for the clabernetes runtime",
	)
	c.PersistentFlags().DurationVarP(
		&o.Global.Timeout,
		"timeout",
		"",
		o.Global.Timeout,
		"timeout for external API requests (e.g. container runtimes); lab runtimes default to 10m",
	)
	c.PersistentFlags().StringVarP(
		&o.Global.Runtime,
		"runtime",
		"r",
		o.Global.Runtime,
		"container runtime",
	)
	c.PersistentFlags().StringVarP(
		&o.Global.LogLevel,
		"log-level",
		"",
		o.Global.LogLevel,
		"logging level; one of [trace, debug, info, warning, error, fatal]",
	)

	err := c.MarkPersistentFlagFilename("topo", "*.yaml", "*.yml")
	if err != nil {
		return nil, err
	}

	for _, f := range subcommandRegisterFuncs() {
		cmd, err := f(o)
		if err != nil {
			return nil, err
		}

		c.AddCommand(cmd)
	}

	// Initialize viper for environment variable support
	if err := initViper(c); err != nil {
		return nil, err
	}

	return c, nil
}

func preRunFn(cobraCmd *cobra.Command, o *Options) error {
	// Update options from viper (environment variables take precedence over defaults)
	if v != nil {
		updateOptionsFromViper(cobraCmd, o)
	}
	applyLabRuntimeDefaultTimeout(cobraCmd, o)

	// setting log level
	switch {
	case o.Global.DebugCount > 0:
		log.SetLevel(log.DebugLevel)
	default:
		l, err := log.ParseLevel(o.Global.LogLevel)
		if err != nil {
			return err
		}

		log.SetLevel(l)
	}

	// initializes the version manager that goes off and fetches current version in
	// the background for us
	initVersionManager(cobraCmd.Context())

	// setting output to stderr, so that json outputs can be parsed
	log.SetOutput(os.Stderr)

	log.SetTimeFormat(time.TimeOnly)

	if err := checkLabRuntimeCommandSupport(cobraCmd, o.Global.Runtime); err != nil {
		return err
	}

	err := clabutils.DropRootPrivs()
	if err != nil {
		return err
	}
	if globalRuntimeRequiresRoot(o.Global.Runtime) {
		err := clabutils.CheckAndGetRootPrivs()
		if err != nil {
			return err
		}
	}

	return getTopoFilePath(cobraCmd, o)
}

// applyLabRuntimeDefaultTimeout gives remote, controller-driven lab runtimes enough time to load
// large node images. An explicit flag or environment value always wins. Local Docker and Podman
// retain their existing two-minute default.
func applyLabRuntimeDefaultTimeout(cobraCmd *cobra.Command, o *Options) {
	if !clablabruntime.IsLabRuntimeName(o.Global.Runtime) {
		return
	}

	timeoutFlag := cobraCmd.Flag("timeout")
	if timeoutFlag != nil && timeoutFlag.Changed {
		return
	}

	if value, ok := os.LookupEnv(envPrefix + "_TIMEOUT"); ok && strings.TrimSpace(value) != "" {
		return
	}

	o.Global.Timeout = defaultLabRuntimeTimeout
}

func globalRuntimeRequiresRoot(name string) bool {
	return name != "" &&
		name != clabruntimedocker.RuntimeName &&
		!commandSkipsRoot(name)
}

func commandSkipsRoot(name string) bool {
	return clablabruntime.IsLabRuntimeName(name)
}

// labRuntimeUnsupportedCommands operate on local containers or host networking
// and have no lab runtime equivalent.
var labRuntimeUnsupportedCommands = map[string]struct{}{
	"tools": {},
}

// graphTopologyFileFlags select graph modes that render from the topology file alone, without
// running containers. Lab runtimes support only these modes.
var graphTopologyFileFlags = []string{ //nolint:gochecknoglobals
	"dot",
	"mermaid",
	"drawio",
	"offline",
}

// labRuntimeUnsupportedFlags is the explicit CLI compatibility contract for controller-driven
// runtimes. A flag listed here must fail before topology parsing or remote mutation instead of
// being accepted and silently ignored by the adapter.
var labRuntimeUnsupportedFlags = map[string][]string{ //nolint:gochecknoglobals
	"deploy": {
		"graph", "ipv4-subnet", "ipv6-subnet", "network", "node-filter",
		"restore", "restore-all", "skip-labdir-acl", "skip-post-deploy", "export-template",
	},
	"destroy": {
		"graceful", "keep-mgmt-net", "node-filter",
	},
	"graph": {
		"node-filter",
	},
	"redeploy": {
		"graceful", "graph", "ipv4-subnet", "ipv6-subnet", "keep-mgmt-net",
		"network", "skip-labdir-acl", "skip-post-deploy", "export-template",
	},
}

func checkLabRuntimeCommandSupport(cobraCmd *cobra.Command, runtimeName string) error {
	if !clablabruntime.IsLabRuntimeName(runtimeName) {
		return nil
	}

	for cmd := cobraCmd; cmd != nil; cmd = cmd.Parent() {
		if _, ok := labRuntimeUnsupportedCommands[cmd.Name()]; ok {
			return fmt.Errorf("the %q command is not supported with lab runtime %q",
				cmd.Name(), runtimeName)
		}
	}

	if getCommandPath(cobraCmd) == "graph" && !graphRendersFromTopologyFile(cobraCmd) {
		return fmt.Errorf(
			"the %q command needs running containers with lab runtime %q unless it renders "+
				"from the topology file alone; use --offline, --dot, --mermaid or --drawio",
			"graph", runtimeName)
	}

	if getCommandPath(cobraCmd) == "inspect.interfaces" {
		return fmt.Errorf("the %q command is not supported with lab runtime %q",
			"inspect interfaces", runtimeName)
	}

	var unsupported []string
	for _, flagName := range labRuntimeUnsupportedFlags[getCommandPath(cobraCmd)] {
		if labRuntimeFlagWasSet(cobraCmd, flagName) {
			unsupported = append(unsupported, "--"+flagName)
		}
	}
	if len(unsupported) != 0 {
		sort.Strings(unsupported)

		return fmt.Errorf(
			"flag(s) %s are not supported with the %q command and lab runtime %q",
			strings.Join(unsupported, ", "),
			cobraCmd.Name(),
			runtimeName,
		)
	}

	return nil
}

func graphRendersFromTopologyFile(cobraCmd *cobra.Command) bool {
	for _, flagName := range graphTopologyFileFlags {
		flag := cobraCmd.Flag(flagName)
		if flag != nil && flag.Value.String() == "true" &&
			labRuntimeFlagWasSet(cobraCmd, flagName) {
			return true
		}
	}

	return false
}

func labRuntimeFlagWasSet(cobraCmd *cobra.Command, flagName string) bool {
	flag := cobraCmd.Flag(flagName)
	if flag == nil {
		return false
	}

	if flag.Changed {
		return true
	}

	if v == nil {
		return false
	}

	commandKey := getCommandPath(cobraCmd) + "." + flagName
	if v.IsSet(commandKey) {
		return true
	}

	return v.IsSet(flagName)
}

// getTopoFilePath finds *.clab.y*ml file in the current working directory
// if the file was not specified.
// If the topology file refers to a git repository, it will be cloned to the current directory.
// Errors if more than one file is found by the glob path.
func getTopoFilePath(cobraCmd *cobra.Command, o *Options) error { // skipcq: GO-R1005
	// set commands which may use topo file find functionality, the rest don't need it
	if cobraCmd.Name() != "deploy" &&
		cobraCmd.Name() != "destroy" &&
		cobraCmd.Name() != "start" &&
		cobraCmd.Name() != "stop" &&
		cobraCmd.Name() != "restart" &&
		cobraCmd.Name() != "redeploy" &&
		cobraCmd.Name() != "inspect" &&
		cobraCmd.Name() != "save" &&
		cobraCmd.Name() != "graph" &&
		cobraCmd.Name() != "validate" &&
		cobraCmd.Name() != "logs" &&
		cobraCmd.Name() != "interfaces" {
		return nil
	}

	// start/stop/restart topology lookup applies only to top-level lifecycle commands.
	// nested commands like tools api-server start|stop are excluded.
	if (cobraCmd.Name() == "start" || cobraCmd.Name() == "stop" || cobraCmd.Name() == "restart") &&
		(cobraCmd.Parent() == nil || cobraCmd.Parent().Name() != "containerlab") {
		return nil
	}

	// inspect and destroy commands with --all flag don't use file find functionality
	if (cobraCmd.Name() == "inspect" || cobraCmd.Name() == "destroy") &&
		cobraCmd.Flag("all") != nil &&
		cobraCmd.Flag("all").Value.String() == "true" {
		return nil
	}

	var err error
	// perform topology clone/fetch if the topo file is not available locally
	if !clabutils.FileOrDirExists(o.Global.TopologyFile) {
		switch {
		case clabgit.IsGitHubOrGitLabURL(o.Global.TopologyFile) ||
			clabgit.IsGitHubShortURL(o.Global.TopologyFile):
			o.Global.TopologyFile, err = processGitTopoFile(o.Global.TopologyFile)
			if err != nil {
				return err
			}
		case clabutils.IsHttpURL(o.Global.TopologyFile, true):
			// canonize the passed topo as URL by adding https schema if it was missing
			if !strings.HasPrefix(o.Global.TopologyFile, "http://") &&
				!strings.HasPrefix(o.Global.TopologyFile, "https://") {
				o.Global.TopologyFile = "https://" + o.Global.TopologyFile
			}
		}
	}

	// if topo or name flags have been provided, don't try to derive the topo file
	if o.Global.TopologyFile != "" || o.Global.TopologyName != "" {
		return nil
	}

	log.Debugf("trying to find topology files automatically")

	files, err := filepath.Glob("*.clab.y*ml")

	if len(files) == 0 {
		return errors.New("no topology files matching the pattern *.clab.yml or *.clab.yaml found")
	}

	if len(files) > 1 {
		if !term.IsTerminal(os.Stdin.Fd()) {
			return fmt.Errorf(
				"more than one topology file matching the pattern *.clab.yml or *.clab.yaml found, "+
					"can't pick one: %q",
				files,
			)
		}

		running := runningTopoFiles(cobraCmd.Context(), o)

		selected, err := selectTopoFile(files, running)
		if err != nil {
			return err
		}

		o.Global.TopologyFile = selected

		log.Info("Using topology file", "file", selected)

		return nil
	}

	o.Global.TopologyFile = files[0]

	log.Debugf("topology file found: %s", files[0])

	return err
}

func processGitTopoFile(topo string) (string, error) {
	// for short github urls, prepend https://github.com
	// note that short notation only works for github links
	if clabgit.IsGitHubShortURL(topo) {
		topo = "https://github.com/" + topo
	}

	repo, err := clabgit.NewRepo(topo)
	if err != nil {
		return "", err
	}

	// Instantiate the git implementation to use.
	gitImpl := clabgit.NewGoGit(repo)

	// clone the repo via the Git Implementation
	err = gitImpl.Clone()
	if err != nil {
		return "", err
	}

	// adjust permissions for the checked out repo
	// it would belong to root/root otherwise
	err = clabutils.SetUIDAndGID(repo.GetName())
	if err != nil {
		log.Errorf("error adjusting repository permissions %v. Continuing anyways", err)
	}

	// prepare the path with the repo based path
	path := filepath.Join(repo.GetPath()...)
	// prepend that path with the repo base directory
	path = filepath.Join(repo.GetName(), path)

	// change dir to the
	err = os.Chdir(path)
	if err != nil {
		return "", err
	}

	return repo.GetFilename(), err
}

