	"k8s.io/client-go/tools/portforward"
	"k8s.io/client-go/tools/remotecommand"
	"k8s.io/client-go/transport/spdy"
	kubeexec "k8s.io/client-go/util/exec"
	streamhttp "k8s.io/streaming/pkg/httpstream"
)

// podMetricsGVR is the resource metrics API metrics-server serves.
var podMetricsGVR = schema.GroupVersionResource{
	Group:    "metrics.k8s.io",
	Version:  "v1beta1",
	Resource: "pods",
}

// defaultAttachCommand runs when an attach request names no command.
var defaultAttachCommand = []string{"sh"} //nolint:gochecknoglobals

// portForwardRequestID numbers the port-forward streams of this process.
var portForwardRequestID atomic.Int64 //nolint:gochecknoglobals

// LocateNode reports the pod, primary device container, Node UID and exposed ports of the
// requested nodes, or of every node of the lab when the request names none. Node names are
// accepted as the topology or as the cluster spells them.
func (r *Runtime) LocateNode(
	ctx context.Context,
	req clablabruntime.NodeRequest,
) ([]clablabruntime.NodeLocation, error) {
	r, err := r.connect(req.Identity)
	if err != nil {
		return nil, err
	}

	state, err := r.Inspect(ctx, clablabruntime.InspectRequest{
		Name:      req.Name,
		Namespace: req.Namespace,
	})
	if err != nil {
		return nil, err
	}

	nodes := make(map[string]clablabruntime.NodeState, len(state.Nodes))
	for _, node := range state.Nodes {
		nodes[node.Name] = node
	}

	if len(req.Nodes) == 0 {
		locations := make([]clablabruntime.NodeLocation, 0, len(state.Nodes))
		for _, node := range state.Nodes {
			locations = append(locations, nodeLocation(state, node))
		}

		return locations, nil
	}

	locations := make([]clablabruntime.NodeLocation, 0, len(req.Nodes))
	for _, nodeName := range req.Nodes {
		resolved, ok := resolveKnownNodeName(nodes, nodeName)
		if !ok {
			return nil, fmt.Errorf("node %q was not found in c9s lab %s/%s",
				nodeName, state.Namespace, state.Name)
		}
		locations = append(locations, nodeLocation(state, nodes[resolved]))
	}

	return locations, nil
}

func nodeLocation(
	state *clablabruntime.LabState,
	node clablabruntime.NodeState,
) clablabruntime.NodeLocation {
	return clablabruntime.NodeLocation{
		NodeName:            node.Name,
		Namespace:           state.Namespace,
		Pod:                 node.Pod,
		Container:           node.Container,
		NodeUID:             node.NodeUID,
		ExposedPorts:        node.ExposedPorts,
		LoadBalancerAddress: node.LoadBalancerAddress,
	}
}

// runningNode locates one node and requires it to have a pod and a device container.
func (r *Runtime) runningNode(
	ctx context.Context,
	lab,
	namespace,
	nodeName string,
) (clablabruntime.NodeLocation, error) {
	if lab == "" {
		return clablabruntime.NodeLocation{}, fmt.Errorf("topology name is required")
	}
	if nodeName == "" {
		return clablabruntime.NodeLocation{}, fmt.Errorf("node name is required")
	}

	locations, err := r.LocateNode(ctx, clablabruntime.NodeRequest{
		Name:      lab,
		Namespace: namespace,
		Nodes:     []string{nodeName},
	})
	if err != nil {
		return clablabruntime.NodeLocation{}, err
	}

	location := locations[0]
	if location.Pod == "" {
		return clablabruntime.NodeLocation{}, fmt.Errorf(
			"c9s node %s/%s/%s has no pod; is it running?",
			location.Namespace, lab, location.NodeName)
	}

	return location, nil
}

// Attach runs an interactive command in a node's device container, or in the container the
// request names, with stdin, an optional TTY and terminal resizing.
func (r *Runtime) Attach(
	ctx context.Context,
	req clablabruntime.AttachRequest,
	streams clablabruntime.AttachStreams,
) error {
	r, err := r.connect(req.Identity)
	if err != nil {
		return err
	}

	location, err := r.runningNode(ctx, req.Name, req.Namespace, req.NodeName)
	if err != nil {
		return err
	}

	container := req.Container
	if container == "" {
		container = location.Container
	}
	command := req.Command
	if len(command) == 0 {
		command = defaultAttachCommand
	}

	stderr := streams.Stderr
	if req.TTY {
		// a terminal merges stderr into stdout
		stderr = nil
	}

	execURL := r.kubeClient.CoreV1().RESTClient().Post().
		Resource("pods").
		Name(location.Pod).
		Namespace(location.Namespace).
		SubResource("exec").
		VersionedParams(&corev1.PodExecOptions{
			Container: container,
			Command:   command,
			Stdin:     streams.Stdin != nil,
			Stdout:    streams.Stdout != nil,
			Stderr:    stderr != nil,
			TTY:       req.TTY,
		}, scheme.ParameterCodec).URL()

	executor, err := r.newExecutor(execURL)
	if err != nil {
		return err
	}

	options := remotecommand.StreamOptions{
		Stdin:  streams.Stdin,
		Stdout: streams.Stdout,
		Stderr: stderr,
		Tty:    req.TTY,
	}
	if req.TTY && streams.Resize != nil {
		options.TerminalSizeQueue = newTerminalSizeQueue(ctx, streams.Resize)
	}

	err = executor.StreamWithContext(ctx, options)

	var exitErr kubeexec.ExitError
	if errors.As(err, &exitErr) {
		return &clablabruntime.CommandExitError{Code: exitErr.ExitStatus()}
	}
	if err != nil {
		return fmt.Errorf("failed to attach to c9s node %s/%s/%s: %w",
			location.Namespace, req.Name, location.NodeName, err)
	}

	return nil
}

// newExecutor streams a pod exec over websockets, falling back to SPDY when the API server
// does not upgrade the websocket, like kubectl. The websocket executor reports upgrade
// failures with the k8s.io/streaming error types. Both transports are built from the runtime's
// rest config, so they carry its impersonation headers.
func (r *Runtime) newExecutor(execURL *url.URL) (remotecommand.Executor, error) {
	websocketExecutor, err := remotecommand.NewWebSocketExecutor(
		r.restConfig, http.MethodGet, execURL.String())
	if err != nil {
		return nil, fmt.Errorf("failed to create Kubernetes websocket exec executor: %w", err)
	}

	spdyExecutor, err := remotecommand.NewSPDYExecutor(r.restConfig, http.MethodPost, execURL)
	if err != nil {
		return nil, fmt.Errorf("failed to create Kubernetes exec executor: %w", err)
	}

	return remotecommand.NewFallbackExecutor(websocketExecutor, spdyExecutor,
		func(err error) bool {
			return streamhttp.IsUpgradeFailure(err) || streamhttp.IsHTTPSProxyError(err)
		})
}

// terminalSizeQueue adapts a resize channel to the remotecommand size queue.
type terminalSizeQueue struct {
	ctx    context.Context
	resize <-chan clablabruntime.TerminalSize
}

func newTerminalSizeQueue(
	ctx context.Context,
	resize <-chan clablabruntime.TerminalSize,
) *terminalSizeQueue {
	return &terminalSizeQueue{ctx: ctx, resize: resize}
}

// Next blocks until the next size change; nil ends resizing.
func (q *terminalSizeQueue) Next() *remotecommand.TerminalSize {
	select {
	case <-q.ctx.Done():
		return nil
	case size, ok := <-q.resize:
		if !ok {
			return nil
		}

		return &remotecommand.TerminalSize{Width: size.Width, Height: size.Height}
	}
}

// StreamLogs writes the log of a node's device container, or of the container the request
// names, to w.
func (r *Runtime) StreamLogs(
	ctx context.Context,
	req clablabruntime.LogRequest,
	w io.Writer,
) error {
	r, err := r.connect(req.Identity)
	if err != nil {
		return err
	}

	location, err := r.runningNode(ctx, req.Name, req.Namespace, req.NodeName)
	if err != nil {
		return err
	}

	container := req.Container
	if container == "" {
		container = location.Container
	}

	stream, err := r.kubeClient.CoreV1().Pods(location.Namespace).
		GetLogs(location.Pod, &corev1.PodLogOptions{
			Container:  container,
			Follow:     req.Follow,
			Timestamps: req.Timestamps,
			TailLines:  req.Tail,
		}).Stream(ctx)
	if err != nil {
		return fmt.Errorf("failed to stream the log of c9s node %s/%s/%s: %w",
			location.Namespace, req.Name, location.NodeName, err)
	}
	defer stream.Close()

	if _, err := io.Copy(w, stream); err != nil && ctx.Err() == nil {
		return fmt.Errorf("failed to stream the log of c9s node %s/%s/%s: %w",
			location.Namespace, req.Name, location.NodeName, err)
	}

	return nil
}

// DialPort opens a connection to a TCP port of a node's pod through the Kubernetes port-forward
// subresource.
func (r *Runtime) DialPort(
	ctx context.Context,
	req clablabruntime.NodeRequest,
	port int,
) (net.Conn, error) {
	r, err := r.connect(req.Identity)
	if err != nil {
		return nil, err
	}

	if len(req.Nodes) != 1 {
		return nil, fmt.Errorf("port-forward needs exactly one node, got %d", len(req.Nodes))
	}
	if port <= 0 || port > 65535 {
		return nil, fmt.Errorf("invalid port %d", port)
	}

	location, err := r.runningNode(ctx, req.Name, req.Namespace, req.Nodes[0])
	if err != nil {
		return nil, err
	}

	conn, err := r.dialPodPort(location.Namespace, location.Pod, port)
	if err != nil {
		return nil, fmt.Errorf("failed to port-forward to port %d of c9s node %s/%s/%s: %w",
			port, location.Namespace, req.Name, location.NodeName, err)
	}

	return conn, nil
}

// dialPodPort opens a forwarded connection to a pod port over SPDY. The transport is built
// from the runtime's rest config, so it carries its impersonation headers.
func (r *Runtime) dialPodPort(namespace, pod string, port int) (net.Conn, error) {
	forwardURL := r.kubeClient.CoreV1().RESTClient().Post().
		Resource("pods").
		Name(pod).
		Namespace(namespace).
		SubResource("portforward").URL()

	transport, upgrader, err := spdy.RoundTripperFor(r.restConfig)
	if err != nil {
		return nil, fmt.Errorf("failed to create Kubernetes port-forward transport: %w", err)
	}

	dialer := spdy.NewDialer(upgrader, &http.Client{Transport: transport}, http.MethodPost,
		forwardURL)

	streamConn, _, err := dialer.Dial(portforward.PortForwardProtocolV1Name)
	if err != nil {
		return nil, err
	}

	conn, err := newPortForwardConn(streamConn, port)
	if err != nil {
		_ = streamConn.Close()

		return nil, err
	}

	return conn, nil
}

// newPortForwardConn opens the error and data streams of one forwarded connection and returns
// one end of an in-memory pipe whose other end is copied to and from the data stream. The pipe
// gives the caller a complete net.Conn, deadlines included.
func newPortForwardConn(streamConn httpstream.Connection, port int) (net.Conn, error) {
	requestID := strconv.FormatInt(portForwardRequestID.Add(1), 10)

	headers := http.Header{}
	headers.Set(corev1.StreamType, corev1.StreamTypeError)
	headers.Set(corev1.PortHeader, strconv.Itoa(port))
	headers.Set(corev1.PortForwardRequestIDHeader, requestID)

	errorStream, err := streamConn.CreateStream(headers)
	if err != nil {
		return nil, fmt.Errorf("failed to create the error stream: %w", err)
	}
	// the client sends nothing on the error stream
	_ = errorStream.Close()

	headers.Set(corev1.StreamType, corev1.StreamTypeData)
	dataStream, err := streamConn.CreateStream(headers)
	if err != nil {
		return nil, fmt.Errorf("failed to create the data stream: %w", err)
	}

	local, remote := net.Pipe()

	var closeOnce sync.Once
	closeAll := func() {
		closeOnce.Do(func() {
			_ = remote.Close()
			_ = dataStream.Reset()
			_ = streamConn.Close()
		})
	}

	go func() {
		// the API server reports a failure to reach the port on the error stream
		message, _ := io.ReadAll(errorStream)
		if len(message) != 0 {
			_ = remote.Close()
		}
	}()

	go func() {
		defer closeAll()
		_, _ = io.Copy(remote, dataStream)
	}()

	go func() {
		defer closeAll()
		_, _ = io.Copy(dataStream, remote)
	}()

	go func() {
		<-streamConn.CloseChan()
		closeAll()
	}()

	return local, nil
}

// SampleStats reports the CPU and memory usage of every running node of a lab from the
// resource metrics API, summing the node's device containers.
func (r *Runtime) SampleStats(
	ctx context.Context,
	req clablabruntime.InspectRequest,
) ([]clablabruntime.NodeStats, error) {
	r, err := r.connect(req.Identity)
	if err != nil {
		return nil, err
	}

	state, err := r.Inspect(ctx, req)
	if err != nil {
		return nil, err
	}

	metricsList, err := r.client.Resource(podMetricsGVR).Namespace(state.Namespace).
		List(ctx, metav1.ListOptions{})
	if err != nil {
		if apierrors.IsNotFound(err) || apierrors.IsServiceUnavailable(err) ||
			apierrors.IsMethodNotSupported(err) {
			return nil, fmt.Errorf("%w: %v", clablabruntime.ErrMetricsUnavailable, err)
		}

		return nil, fmt.Errorf("failed to read pod metrics in namespace %s: %w",
			state.Namespace, err)
	}

	metricsByPod := make(map[string]*unstructured.Unstructured, len(metricsList.Items))
	for idx := range metricsList.Items {
		metricsByPod[metricsList.Items[idx].GetName()] = &metricsList.Items[idx]
	}

	deviceContainers, err := r.nodeDeviceContainers(ctx, state)
	if err != nil {
		return nil, err
	}

	stats := make([]clablabruntime.NodeStats, 0, len(state.Nodes))
	for _, node := range state.Nodes {
		podMetrics := metricsByPod[node.Pod]
		if node.Pod == "" || podMetrics == nil {
			continue
		}

		containers := deviceContainers[node.Name]
		if len(containers) == 0 && node.Container != "" {
			containers = map[string]bool{node.Container: true}
		}

		sample, ok := podMetricsSample(podMetrics, containers)
		if !ok {
			continue
		}

		sample.NodeName = node.Name
		sample.Namespace = state.Namespace
		sample.Pod = node.Pod
		stats = append(stats, sample)
	}

	return stats, nil
}

// nodeDeviceContainers reads the device containers of every node from its Node status.
func (r *Runtime) nodeDeviceContainers(
	ctx context.Context,
	state *clablabruntime.LabState,
) (map[string]map[string]bool, error) {
	nodes, err := r.nodesForTopology(ctx, state.Name, state.Namespace)
	if err != nil {
		return nil, err
	}

	result := make(map[string]map[string]bool, len(nodes.Items))
	for idx := range nodes.Items {
		directContainers, _, _ := unstructured.NestedSlice(
			nodes.Items[idx].Object, "status", "directContainers")

		names := map[string]bool{}
		for _, raw := range directContainers {
			entry, ok := raw.(map[string]any)
			if !ok {
				continue
			}
			if name, _ := entry["name"].(string); name != "" {
				names[name] = true
			}
		}
		result[nodes.Items[idx].GetName()] = names
	}

	return result, nil
}

// podMetricsSample sums the usage of the given containers of a PodMetrics object.
func podMetricsSample(
	podMetrics *unstructured.Unstructured,
	containers map[string]bool,
) (clablabruntime.NodeStats, bool) {
	rawContainers, _, _ := unstructured.NestedSlice(podMetrics.Object, "containers")

	var (
		cpu    resource.Quantity
		memory resource.Quantity
		found  bool
	)
	for _, raw := range rawContainers {
		entry, ok := raw.(map[string]any)
		if !ok {
			continue
		}
		name, _ := entry["name"].(string)
		if !containers[name] {
			continue
		}

		usage, _ := entry["usage"].(map[string]any)
		if value, ok := usage["cpu"].(string); ok {
			if quantity, err := resource.ParseQuantity(value); err == nil {
				cpu.Add(quantity)
			}
		}
		if value, ok := usage["memory"].(string); ok {
			if quantity, err := resource.ParseQuantity(value); err == nil {
				memory.Add(quantity)
			}
		}
		found = true
	}
	if !found {
		return clablabruntime.NodeStats{}, false
	}

	sample := clablabruntime.NodeStats{
		CPUMilliCores: cpu.MilliValue(),
		MemoryBytes:   memory.Value(),
	}
	if value, _, _ := unstructured.NestedString(podMetrics.Object, "timestamp"); value != "" {
		sample.Timestamp, _ = time.Parse(time.RFC3339, value)
	}
	if value, _, _ := unstructured.NestedString(podMetrics.Object, "window"); value != "" {
		sample.Window, _ = time.ParseDuration(value)
	}

	return sample, true
}

package labruntime

import (
	"context"
	"errors"
	"fmt"
	"io"
	"net"
	"slices"
	"strings"
	"time"

	clabexec "github.com/srl-labs/containerlab/exec"
	clabtypes "github.com/srl-labs/containerlab/types"
)

const (
	ClabernetesRuntimeName = "c9s"

	ExposeTypeClusterIP    = "ClusterIP"
	ExposeTypeHeadless     = "Headless"
	ExposeTypeLoadBalancer = "LoadBalancer"
	ExposeTypeNone         = "None"
)

var exposeTypes = map[string]string{ //nolint:gochecknoglobals
	strings.ToLower(ExposeTypeClusterIP):    ExposeTypeClusterIP,
	strings.ToLower(ExposeTypeHeadless):     ExposeTypeHeadless,
	strings.ToLower(ExposeTypeLoadBalancer): ExposeTypeLoadBalancer,
	strings.ToLower(ExposeTypeNone):         ExposeTypeNone,
}

// NormalizeExposeType validates a c9s expose type and returns its canonical CRD spelling.
func NormalizeExposeType(value string) (string, error) {
	if value == "" {
		return "", nil
	}
	if normalized, ok := exposeTypes[strings.ToLower(value)]; ok {
		return normalized, nil
	}

	return "", fmt.Errorf("invalid expose type %q; must be one of %s, %s, %s, %s",
		value,
		ExposeTypeClusterIP,
		ExposeTypeHeadless,
		ExposeTypeLoadBalancer,
		ExposeTypeNone,
	)
}

// Identity is the Kubernetes identity a lab runtime acts as, through user impersonation. The
// zero value acts with the configured credentials (the kubeconfig) as they are. A server that
// runs labs for many users sets it per call, so the cluster's RBAC and audit log see the user.
type Identity struct {
	User   string
	Groups []string
}

// IsZero reports whether the identity leaves the configured credentials as they are.
func (i Identity) IsZero() bool {
	return i.User == "" && len(i.Groups) == 0
}

// Equal reports whether two identities impersonate the same user and groups.
func (i Identity) Equal(other Identity) bool {
	return i.User == other.User && slices.Equal(i.Groups, other.Groups)
}

type Config struct {
	Timeout   time.Duration
	Namespace string
	// Identity is the identity of every call that does not set its own.
	Identity Identity

	// KindLinkApplyMode resolves the default link apply mode ("live", "restart" or
	// "recreate") a node kind declares, as containerlab's node registry reports it. An
	// empty result means the kind is unknown and the conservative recreate default
	// applies. Lab runtimes use it to predict the node lifecycle impact of link changes.
	KindLinkApplyMode func(kind string) string
}

type DeployRequest struct {
	Name               string
	Namespace          string
	Owner              string
	TopologyFile       string
	TopologyLabDir     string
	TopologyDefinition []byte
	Wait               bool
	Timeout            time.Duration
	// MaxWorkers limits concurrent independent operations performed by the runtime.
	MaxWorkers uint
	// NoTopologyCR deploys without a controller-owned topology object: the runtime compiles the
	// topology client-side and manages the individual lab resources directly.
	NoTopologyCR bool
	// ImagePullSecret names the same-namespace Docker-config Secret placed on device pods
	// through Pod.spec.imagePullSecrets. Empty means the lab references no pull secret at
	// all: public images and clusters whose runtime already holds credentials need none.
	ImagePullSecret string
	// ExposeType controls the Kubernetes Service type c9s creates for lab nodes. Empty uses the
	// c9s CRD default.
	ExposeType string
	// NoPersistence deploys the lab on ephemeral node storage. By default every node's
	// artifact volume is backed by a persistent claim so saved device configuration survives
	// Pod replacement, matching the local-runtime lab directory contract; opting out trades
	// that for not needing a dynamically provisionable storage class, and every Pod
	// replacement then resets the node to its declared configuration.
	NoPersistence bool
	// Identity overrides the runtime's configured identity for this call.
	Identity Identity
}

type DestroyRequest struct {
	Name       string
	Namespace  string
	Wait       bool
	Timeout    time.Duration
	MaxWorkers uint
	// Cleanup also deletes the lab's persistent node storage (saved configuration). Without
	// it the storage is kept, like the lab directory of a local runtime, and a later deploy
	// of the lab boots from it.
	Cleanup bool
	// Identity overrides the runtime's configured identity for this call.
	Identity Identity
}

type InspectRequest struct {
	Name      string
	Namespace string
	// Identity overrides the runtime's configured identity for this call.
	Identity Identity
}

// ListRequest selects the labs List reports. A Namespace, or the runtime's configured
// namespace override, limits the listing to that namespace, even with AllNamespaces.
type ListRequest struct {
	Namespace     string
	AllNamespaces bool
	// Identity overrides the runtime's configured identity for this call.
	Identity Identity
}

type NodeRequest struct {
	Name      string
	Namespace string
	Nodes     []string
	Timeout   time.Duration
	// Identity overrides the runtime's configured identity for this call.
	Identity Identity
}

type ExecRequest struct {
	Name      string
	Namespace string
	NodeName  string
	Command   []string
	// Identity overrides the runtime's configured identity for this call.
	Identity Identity
}

type SaveRequest struct {
	Name      string
	Namespace string
	Nodes     []string
	Copy      bool
	// Identity overrides the runtime's configured identity for this call.
	Identity Identity
}

// EventStreamRequest selects the events StreamEvents reports. Name limits the stream to one
// lab, in its namespace. Without Name, Namespace or the runtime's configured namespace override
// limit it to one namespace; AllNamespaces otherwise covers every namespace.
type EventStreamRequest struct {
	Name                  string
	Namespace             string
	AllNamespaces         bool
	IncludeInitialState   bool
	IncludeInterfaceStats bool
	StatsInterval         time.Duration
	// Identity overrides the runtime's configured identity for this call.
	Identity Identity
}

type SavedFile struct {
	NodeName   string
	Name       string
	Data       []byte
	Mode       int64
	LinkTarget string
}

type SaveResult struct {
	Files []SavedFile
}

type NodeState struct {
	Name  string
	Kind  string
	Image string
	State string
	Ready bool
	// MgmtIPv4Address and MgmtIPv6Address are the node's allocated management addresses in
	// CIDR notation, when the runtime reports them.
	MgmtIPv4Address     string
	MgmtIPv6Address     string
	LoadBalancerAddress string
	// Pod is the pod that runs the node. Nodes that share a network namespace share a pod.
	Pod string
	// Container is the node's primary device container in Pod.
	Container string
	// NodeUID identifies the runtime's node resource (the clabernetes Node UID).
	NodeUID string
	// ExposedPorts are the node ports the runtime publishes through a Service.
	ExposedPorts []ExposedPort
}

// ExposedPort is a node port a lab runtime publishes through a Service.
type ExposedPort = clabtypes.ExposedPort

type LabState struct {
	Name         string
	Namespace    string
	Owner        string
	TopologyPath string
	State        string
	Ready        bool
	Nodes        []NodeState
}

type ChangeAction string

const (
	ChangeCreate ChangeAction = "create"
	ChangeUpdate ChangeAction = "update"
	ChangeDelete ChangeAction = "delete"
	// ChangeRecreate marks a resource that is deleted and created again, such as the Pod
	// of a node whose links change. It is not a Kubernetes action; it communicates the
	// lifecycle impact of an apply.
	ChangeRecreate ChangeAction = "recreate"
)

type ResourceChange struct {
	Action    ChangeAction `json:"action"`
	Kind      string       `json:"kind"`
	Namespace string       `json:"namespace,omitempty"`
	Name      string       `json:"name"`
}

// DeployPlan describes the remote resources a lab runtime would change without mutating them.
type DeployPlan struct {
	LabName   string           `json:"lab-name"`
	Namespace string           `json:"namespace"`
	Changes   []ResourceChange `json:"changes"`
}

type Event struct {
	Timestamp   time.Time
	Type        string
	Action      string
	ActorID     string
	ActorName   string
	ActorFullID string
	Attributes  map[string]string
}

// NodeLocation is the workload that runs a lab node.
type NodeLocation struct {
	// NodeName is the node name the runtime carries (the sanitized name).
	NodeName  string
	Namespace string
	Pod       string
	// Container is the node's primary device container in Pod.
	Container string
	// NodeUID identifies the runtime's node resource (the clabernetes Node UID).
	NodeUID string
	// ExposedPorts are the node ports the runtime publishes through a Service.
	ExposedPorts        []ExposedPort
	LoadBalancerAddress string
}

// TerminalSize is the size of an interactive terminal, in characters.
type TerminalSize struct {
	Width  uint16
	Height uint16
}

// AttachRequest selects the node and the command of an interactive session.
type AttachRequest struct {
	// Name is the lab name.
	Name      string
	Namespace string
	// NodeName is the node to attach to, as the topology or the runtime names it.
	NodeName string
	// Container overrides the node's primary device container.
	Container string
	// Command runs in the container; empty runs "sh".
	Command []string
	// TTY allocates a terminal. Stdout then carries the combined output, and Resize applies.
	TTY      bool
	Identity Identity
}

// AttachStreams connects an interactive session. Nil streams are not attached.
type AttachStreams struct {
	Stdin  io.Reader
	Stdout io.Writer
	Stderr io.Writer
	// Resize delivers terminal size changes of a TTY session; closing it stops resizing.
	Resize <-chan TerminalSize
}

// CommandExitError reports a command that ran and exited with a nonzero code.
type CommandExitError struct {
	Code int
}

func (e *CommandExitError) Error() string {
	return fmt.Sprintf("command exited with code %d", e.Code)
}

// LogRequest selects the node log StreamLogs writes.
type LogRequest struct {
	// Name is the lab name.
	Name      string
	Namespace string
	// NodeName is the node whose log is streamed, as the topology or the runtime names it.
	NodeName string
	// Container overrides the node's primary device container.
	Container string
	// Tail limits the output to the last lines of the log; nil writes the whole log.
	Tail *int64
	// Follow keeps streaming new log lines until the context ends.
	Follow bool
	// Timestamps prefixes every line with its timestamp.
	Timestamps bool
	Identity   Identity
}

// NodeStats is a resource usage sample of a node.
type NodeStats struct {
	NodeName  string
	Namespace string
	Pod       string
	// CPUMilliCores is the CPU usage of the node's device containers, in thousandths of a core.
	CPUMilliCores int64
	// MemoryBytes is the memory working set of the node's device containers.
	MemoryBytes int64
	// Timestamp and Window describe the sampling interval the usage was measured over.
	Timestamp time.Time
	Window    time.Duration
}

// ErrMetricsUnavailable reports a cluster without a resource metrics API (metrics.k8s.io), for
// example one without metrics-server.
var ErrMetricsUnavailable = errors.New("metrics API (metrics.k8s.io) not available")

// NodeLocator resolves lab nodes to the workloads that run them. Empty NodeRequest.Nodes
// locates every node of the lab.
type NodeLocator interface {
	LocateNode(ctx context.Context, req NodeRequest) ([]NodeLocation, error)
}

// NodeAttacher runs an interactive command (stdin, TTY and resize) in a node's container. It
// returns a *CommandExitError when the command exits with a nonzero code.
type NodeAttacher interface {
	Attach(ctx context.Context, req AttachRequest, streams AttachStreams) error
}

// NodeLogStreamer writes a node container's log.
type NodeLogStreamer interface {
	StreamLogs(ctx context.Context, req LogRequest, w io.Writer) error
}

// NodePortForwarder opens a stream to a TCP port of a node (SSH, web UIs). The request must name
// exactly one node. Closing the connection closes the stream.
type NodePortForwarder interface {
	DialPort(ctx context.Context, req NodeRequest, port int) (net.Conn, error)
}

// NodeStatsSampler reports the resource usage of a lab's nodes. It returns an error wrapping
// ErrMetricsUnavailable when the cluster serves no resource metrics.
type NodeStatsSampler interface {
	SampleStats(ctx context.Context, req InspectRequest) ([]NodeStats, error)
}

type LabRuntime interface {
	Deploy(context.Context, DeployRequest) (*LabState, error)
	Destroy(context.Context, DestroyRequest) error
	Inspect(context.Context, InspectRequest) (*LabState, error)
	List(context.Context, ListRequest) ([]*LabState, error)
	Exec(context.Context, ExecRequest) (*clabexec.ExecResult, error)
	Start(context.Context, NodeRequest) error
	Stop(context.Context, NodeRequest) error
	Restart(context.Context, NodeRequest) error
	Save(context.Context, SaveRequest) (*SaveResult, error)
	StreamEvents(context.Context, EventStreamRequest) (<-chan Event, <-chan error, error)
}

// LabExistenceChecker lets controller-driven runtimes report whether a lab has remote state.
// Core uses it to distinguish a fresh deployment from reconciliation without consulting the
// local container runtime.
type LabExistenceChecker interface {
	LabExists(context.Context, InspectRequest) (bool, error)
}

// TopologyValidator validates the runtime-specific topology subset without changing remote state.
type TopologyValidator interface {
	Validate(context.Context, DeployRequest) error
}

// TopologyPlanner compiles and diffs a desired topology without changing remote state.
type TopologyPlanner interface {
	Plan(context.Context, DeployRequest) (*DeployPlan, error)
}

// Manifest is one remote resource a lab runtime would create for a topology, ready to be
// serialized and applied by hand. Object is the complete resource including its type and
// metadata; the identity fields are duplicated for summaries and tests.
type Manifest struct {
	APIVersion string
	Kind       string
	Namespace  string
	Name       string
	Object     map[string]any
}

// ManifestEmitter renders the exact resources a lab runtime would create for a topology, in
// apply order, without reading or changing remote state.
type ManifestEmitter interface {
	Manifests(context.Context, DeployRequest) ([]Manifest, error)
}

type Initializer func(Config) (LabRuntime, error)

var LabRuntimes = map[string]Initializer{}

func Register(name string, init Initializer) {
	LabRuntimes[name] = init
}

func IsLabRuntimeName(name string) bool {
	_, ok := LabRuntimes[strings.ToLower(name)]
	return ok
}

func Init(name string, cfg Config) (LabRuntime, error) {
	name = strings.ToLower(name)
	init, ok := LabRuntimes[name]
	if !ok {
		return nil, fmt.Errorf("unknown lab runtime %q", name)
	}

	return init(cfg)
}

