type Options struct {
	Global         *GlobalOptions
	Filter         *FilterOptions
	NodeLifecycle  *NodeLifecycleOptions
	Deploy         *DeployOptions
	Destroy        *DestroyOptions
	Save           *SaveOptions
	Exec           *ExecOptions
	Inspect        *InspectOptions
	Graph          *GraphOptions
	Events         *EventsOptions
	Logs           *LogsOptions
	ToolsAPI       *ToolsApiOptions
	ToolsCert      *ToolsCertOptions
	ToolsTxOffload *ToolsDisableTxOffloadOptions
	ToolsGoTTY     *ToolsGoTTYOptions
	ToolsNetem     *ToolsNetemOptions
	ToolsSSHX      *ToolsSSHXOptions
	ToolsVeth      *ToolsVethOptions
	ToolsVxlan     *ToolsVxlanOptions
	ToolsSnapshot  *ToolsSnapshotOptions
	Version        *VersionOptions
}

func (o *Options) ToClabOptions() []clabcore.ClabOption {
	var clabOptions []clabcore.ClabOption

	clabOptions = append(
		clabOptions,
		o.Global.toClabOptions()...,
	)

	clabOptions = append(
		clabOptions,
		o.Filter.toClabOptions()...,
	)

	clabOptions = append(
		clabOptions,
		o.Deploy.toClabOptions()...,
	)

	clabOptions = append(
		clabOptions,
		o.Destroy.toClabOptions()...,
	)

	return clabOptions
}

func (o *Options) ToClabDestroyOptions() []clabcore.DestroyOption {
	destroyOptions := []clabcore.DestroyOption{
		clabcore.WithDestroyMaxWorkers(o.Deploy.MaxWorkers),
		clabcore.WithDestroyNodeFilter(o.Filter.NodeFilter),
	}

	if o.Destroy.KeepManagementNetwork {
		destroyOptions = append(
			destroyOptions,
			clabcore.WithDestroyKeepMgmtNet(),
		)
	}

	if o.Destroy.Cleanup {
		destroyOptions = append(
			destroyOptions,
			clabcore.WithDestroyCleanup(),
		)
	}

	if o.Global.GracefulShutdown {
		destroyOptions = append(
			destroyOptions,
			clabcore.WithDestroyGraceful(),
		)
	}

	if o.Destroy.All {
		destroyOptions = append(
			destroyOptions,
			clabcore.WithDestroyAll(),
		)

		if !o.Destroy.AutoApprove {
			destroyOptions = append(
				destroyOptions,
				clabcore.WithDestroyTerminalPrompt(),
			)
		}
	}

	if len(o.Global.VarsFiles) != 0 {
		destroyOptions = append(
			destroyOptions,
			clabcore.WithDestroyVarsFiles(o.Global.VarsFiles),
		)
	}

	return destroyOptions
}

func (o *Options) ToClabSaveOptions() []clabcore.SaveOption {
	if o.Save == nil || o.Save.Copy == "" {
		return nil
	}

	return []clabcore.SaveOption{
		clabcore.WithCopyOut(o.Save.Copy),
	}
}

type GlobalOptions struct {
	TopologyFile     string
	VarsFiles        []string
	TopologyName     string
	Namespace        string
	Timeout          time.Duration
	Runtime          string
	GracefulShutdown bool
	LogLevel         string
	DebugCount       int

	// special flag that should only be set by deploy, informs the context handler to destroy
	// (or not) when root context is canceled. The signal handler goroutine reads it while
	// deploy is running, so it is atomic.
	CleanOnCancel atomic.Bool

	// special flag that is only set on deploy,
	// if true, the topology file backup is created at /tmp/.clab/bak
	BackupTopologyFile bool
}

func (o *GlobalOptions) toClabOptions() []clabcore.ClabOption {
	options := []clabcore.ClabOption{
		clabcore.WithTimeout(o.Timeout),
		clabcore.WithRuntime(
			o.Runtime,
			&clabruntime.RuntimeConfig{
				Debug:            o.DebugCount > 0,
				Timeout:          o.Timeout,
				GracefulShutdown: o.GracefulShutdown,
				LabNamespace:     o.Namespace,
			},
		),
		clabcore.WithDebug(o.DebugCount > 0),
	}

	if o.TopologyFile != "" {
		options = append(options, clabcore.WithTopoPath(o.TopologyFile, o.VarsFiles))
	} else if len(o.VarsFiles) != 0 {
		options = append(options, clabcore.WithTopologyVarsFiles(o.VarsFiles))
	}

	if o.TopologyName != "" {
		options = append(options, clabcore.WithTopologyName(o.TopologyName))
	}

	if o.TopologyFile == "" && o.TopologyName != "" &&
		!clablabruntime.IsLabRuntimeName(o.Runtime) {
		options = append(options, clabcore.WithTopologyFromLab(o.TopologyName, o.VarsFiles))
	}

	if o.BackupTopologyFile && o.TopologyFile != "" {
		options = append(options, clabcore.WithTopoBackup(o.TopologyFile))
	}

	return options
}

